        "source": "# Activation function factory\ndef get_activation(name):\n    activations = {\n        'relu': nn.ReLU(),\n        'sigmoid': nn.Sigmoid(),\n        'tanh': nn.Tanh(),\n        'leaky_relu': nn.LeakyReLU(0.1),\n        'gelu': nn.GELU(),\n        'elu': nn.ELU(),\n    }\n    if name not in activations:\n        raise ValueError(f\"Unknown activation: {name}. Available: {list(activations.keys())}\")\n    return activations[name]\n\n# Model definition\nclass FashionMLP(nn.Module):\n    def __init__(self, activation_name='relu'):\n        super(FashionMLP, self).__init__()\n        self.flatten = nn.Flatten()\n        self.fc1 = nn.Linear(784, 256)\n        self.act1 = get_activation(activation_name)\n        self.fc2 = nn.Linear(256, 128)\n        self.act2 = get_activation(activation_name)\n        self.fc3 = nn.Linear(128, 10)\n        \n        # Store layer names for gradient tracking\n        self.layer_names = ['fc1', 'fc2', 'fc3']\n    \n    def forward(self, x):\n        x = self.flatten(x)\n        x = self.fc1(x)\n        x = self.act1(x)\n        x = self.fc2(x)\n        x = self.act2(x)\n        x = self.fc3(x)\n        return x\n\n# Initialize model\nmodel = FashionMLP(ACTIVATION).to(device)\nprint(f\"\\nModel Architecture:\")\nprint(model)\nprint(f\"\\nTotal parameters: {sum(p.numel() for p in model.parameters()):,}\")",
